def process_text(text: str) -> list:
    """
    Splits text by whitespace if present, else by comma,
    else counts lowercase letters with odd alphabetical positions.
    """
    if not text:
        return []

    # Check for any whitespace characters
    if any(c.isspace() for c in text):
        return text.split()

    # Check for comma
    if ',' in text:
        return text.split(',')

    # Else: count lowercase letters with odd alphabetical positions
    # a=1 (odd), b=2 (even), c=3 (odd), etc.
    return [
        char for char in text
        if char.islower() and (ord(char) - ord('a') + 1) % 2 == 1
    ]

