def find_max_nesting_per_group(data, group_by, nesting_key='children'):
    """
    Find the maximum nesting depth per group.

    Args:
        data (list): List of dictionaries.
        group_by (str): Key to group by.
        nesting_key (str): Key representing nested items (default: 'children').

    Returns:
        dict: Mapping of group values to maximum nesting depth.
    """
    def get_depth(item):
        """Recursively calculate the depth of an item."""
        children = item.get(nesting_key, [])
        if not children:
            return 1
        return 1 + max(map(get_depth, children), default=0)

    def group_items(items, key):
        """Group items by a key."""
        from functools import reduce
        return reduce(
            lambda acc, item: {**acc, item[key]: acc.get(item[key], []) + [item]},
            items,
            {}
        )

    grouped = group_items(data, group_by)
    return {
        group: max(map(get_depth, items), default=0)
        for group, items in grouped.items()
    }

