def count_sevens(n, divisors=(11, 13)):
    """
    Counts occurrences of digit '7' in numbers divisible by 11 or 13 within range [0, n).

    Args:
        n: Upper bound (exclusive) of the range [0, n)
        divisors: Tuple of divisors to check (default: (11, 13))

    Returns:
        Total count of digit '7' occurrences
    """
    if n <= 0:
        return 0

    def count_sevens_in_number(num):
        """Count occurrences of digit '7' in a number."""
        return str(num).count('7')

    def is_divisible_by_any(num, divisors):
        """Check if number is divisible by any of the given divisors."""
        return any(num % d == 0 for d in divisors)

    # Functional approach: use sum with generator expression
    return sum(
        count_sevens_in_number(i)
        for i in range(n)
        if is_divisible_by_any(i, divisors)
    )

# Example usage
