def compute_factorial(n):
    """Compute n! using recursion."""
    if n <= 1:
        return 1
    return n * compute_factorial(n - 1)

def compute_product_of_factorials(n):
    """Compute the product of factorials from 1! to n!."""
    if n < 1:
        return 1

    def product_loop(current, acc):
        if current > n:
            return acc
        factorial = compute_factorial(current)
        return product_loop(current + 1, acc * factorial)

    return product_loop(1, 1)

def main():
